bloques.x:
create table clientes (
  id     int generated always as identity primary key,
  nombre text not null unique,
  email  text not null check (email like '%@%')
);
create table depositos (
  id        int generated always as identity primary key,
  nombre    text not null unique,
  direccion text not null
);
create table choferes (
  id       int generated always as identity primary key,
  nombre   text not null,
  licencia text not null unique
);
create table vehiculos (
  id          int generated always as identity primary key,
  patente     text not null unique,
  capacidad_kg int not null check (capacidad_kg > 0)
);
create table rutas (
  id          int generated always as identity primary key,
  fecha       date not null,
  deposito_id int not null references depositos(id),
  chofer_id   int not null references choferes(id),
  vehiculo_id int not null references vehiculos(id),
  unique (chofer_id, fecha),     -- un chofer, una ruta por día
  unique (vehiculo_id, fecha)    -- un vehículo, una ruta por día
);
create table bultos (
  id           int generated always as identity primary key,
  cliente_id   int not null references clientes(id),
  deposito_id  int not null references depositos(id),
  destinatario text not null,
  direccion    text not null,
  peso_kg      numeric(6,2) not null check (peso_kg > 0),
  recibido     date not null
);
create table intentos (
  bulto_id  int not null references bultos(id),
  ruta_id   int not null references rutas(id),
  orden     int not null check (orden > 0),
  resultado text not null check (resultado in ('entregado', 'ausente', 'rechazado', 'direccion_incorrecta')),
  primary key (bulto_id, ruta_id),
  unique (ruta_id, orden)        -- en una ruta, cada parada tiene su número
);
-- un bulto se entrega una sola vez: índice único parcial (los índices vienen más adelante)
create unique index una_entrega_por_bulto on intentos (bulto_id) where resultado = 'entregado';

