select ch.nombre, count(*) filter (where i.resultado = 'entregado') as entregados, count(*) as intentos
from intentos i join rutas r on r.id = i.ruta_id join choferes ch on ch.id = r.chofer_id
group by ch.nombre order by ch.nombre;

